-- FreightFlow SQLite seed data
-- Generated by generate_seed_sql.py
-- CREATE TABLE statements added for SQLite compatibility.

-- Create tables (idempotent)
CREATE TABLE IF NOT EXISTS "shipments_route" (
    "id"                      INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT,
    "route_code"              VARCHAR(10)  NOT NULL UNIQUE,
    "origin_city"             VARCHAR(100) NOT NULL,
    "destination_city"        VARCHAR(100) NOT NULL,
    "distance_km"             DECIMAL(6,2) NOT NULL,
    "typical_duration_hours"  DECIMAL(4,2) NOT NULL
);

CREATE TABLE IF NOT EXISTS "shipments_driver" (
    "id"             INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT,
    "employee_id"    VARCHAR(10)  NOT NULL UNIQUE,
    "full_name"      VARCHAR(200) NOT NULL,
    "license_number" VARCHAR(20)  NOT NULL,
    "phone"          VARCHAR(20)  NOT NULL,
    "hire_date"      DATE         NOT NULL
);

CREATE TABLE IF NOT EXISTS "shipments_shipment" (
    "id"                      INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT,
    "tracking_number"         VARCHAR(15)  NOT NULL UNIQUE,
    "status"                  VARCHAR(20)  NOT NULL,
    "origin_city"             VARCHAR(100) NOT NULL,
    "destination_city"        VARCHAR(100) NOT NULL,
    "weight_kg"               DECIMAL(8,2) NOT NULL,
    "pieces"                  INTEGER      NOT NULL,
    "shipment_date"           DATE         NOT NULL,
    "estimated_delivery"      DATE         NOT NULL,
    "actual_delivery"         DATE,
    "is_delayed"              BOOL         NOT NULL DEFAULT 0,
    "customer_email"          VARCHAR(254) NOT NULL,
    "driver_id"               INTEGER REFERENCES "shipments_driver" ("id") ON DELETE SET NULL,
    "route_id"                INTEGER REFERENCES "shipments_route"  ("id") ON DELETE SET NULL,
    "carrier_tracking_number" VARCHAR(30),
    "proof_of_delivery"       VARCHAR(100)
);

CREATE TABLE IF NOT EXISTS "shipments_telemetry" (
    "id"              INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT,
    "truck_id"        VARCHAR(10)  NOT NULL,
    "tracking_number" VARCHAR(15)  NOT NULL,
    "lat"             DECIMAL(9,6) NOT NULL,
    "lng"             DECIMAL(9,6) NOT NULL,
    "timestamp"       DATETIME     NOT NULL
);

-- Indexes
CREATE INDEX IF NOT EXISTS "shipments_route_route_code"         ON "shipments_route"    ("route_code");
CREATE INDEX IF NOT EXISTS "shipments_driver_employee_id"       ON "shipments_driver"   ("employee_id");
CREATE INDEX IF NOT EXISTS "shipments_shipment_tracking_number" ON "shipments_shipment" ("tracking_number");
CREATE INDEX IF NOT EXISTS "shipments_shipment_status"          ON "shipments_shipment" ("status");
CREATE INDEX IF NOT EXISTS "shipments_shipment_shipment_date"   ON "shipments_shipment" ("shipment_date");
CREATE INDEX IF NOT EXISTS "shipments_telemetry_truck_id"       ON "shipments_telemetry" ("truck_id");
CREATE INDEX IF NOT EXISTS "shipments_telemetry_tracking_number" ON "shipments_telemetry" ("tracking_number");
CREATE INDEX IF NOT EXISTS "shipments_telemetry_timestamp"      ON "shipments_telemetry" ("timestamp");

-- Idempotent reset — telemetry table is preserved.
DELETE FROM shipments_shipment;
DELETE FROM shipments_driver;
DELETE FROM shipments_route;

